import * as THREE from 'three/webgpu';
import { MeshPhysicalNodeMaterial } from 'three/webgpu';
import { color, float } from 'three/tsl';
import gsap from 'gsap';
import { createText } from '@/text';

export default function createNode(config, ctx) {
  const root = new THREE.Group();
  root.name = 'orrery-mechanism';
  root.position.set(0, 0, 0);
  root.rotation.set(0, 0, 0);
  root.scale.set(1, 1, 1);

  const timelines = [];
  const disposables = [];

  const steelMat = new MeshPhysicalNodeMaterial();
  steelMat.colorNode = color('#8a8d92');
  steelMat.roughnessNode = float(0.5);
  steelMat.metalnessNode = float(0.55);
  steelMat.clearcoat = 0.2;
  steelMat.clearcoatRoughness = 0.3;
  steelMat.anisotropy = 0.7;
  disposables.push(steelMat);

  const primaryGroup = new THREE.Group();
  primaryGroup.name = 'gear-primary';
  root.add(primaryGroup);

  const secondaryGroup = new THREE.Group();
  secondaryGroup.name = 'gear-secondary';
  secondaryGroup.position.set(1.15, 0.35, -0.1);
  root.add(secondaryGroup);

  // Load primary gear mesh from GLB
  const gearScene = ctx.glbLoader(config.assets?.meshUrl || '/prism-mock/orrery/meshes/gear-a.glb');
  const primaryMesh = gearScene.scene ? gearScene.scene.clone(true) : gearScene.clone(true);

  const box = new THREE.Box3().setFromObject(primaryMesh);
  const size = new THREE.Vector3();
  box.getSize(size);
  const maxDim = Math.max(size.x, size.y, size.z) || 1;
  const scaleFactor = 1.6 / maxDim;
  primaryMesh.scale.setScalar(scaleFactor);

  const center = new THREE.Vector3();
  box.getCenter(center);
  primaryMesh.position.sub(center.multiplyScalar(scaleFactor));

  primaryMesh.traverse((child) => {
    if (child.isMesh) {
      child.material = steelMat;
      child.castShadow = true;
      child.receiveShadow = true;
    }
  });
  primaryGroup.add(primaryMesh);

  const secondaryMesh = primaryMesh.clone(true);
  const secondaryScale = (0.9 / 1.6);
  secondaryMesh.scale.multiplyScalar(secondaryScale);
  secondaryMesh.traverse((child) => {
    if (child.isMesh) child.material = steelMat;
  });
  secondaryGroup.add(secondaryMesh);

  // Jewel pivot
  const jewelGeo = new THREE.SphereGeometry(0.12, 32, 32);
  const jewelMat = new MeshPhysicalNodeMaterial();
  jewelMat.colorNode = color('#ff2a38');
  jewelMat.transmission = 0.6;
  jewelMat.ior = 1.76;
  jewelMat.emissiveNode = color('#ff2a38').mul(float(1.8));
  jewelMat.roughness = 0.1;
  jewelMat.metalness = 0.0;
  const jewel = new THREE.Mesh(jewelGeo, jewelMat);
  jewel.position.set(0, 0, 0);
  primaryGroup.add(jewel);
  disposables.push(jewelGeo, jewelMat);

  // Arbor shafts
  const shaftGeo = new THREE.CylinderGeometry(0.05, 0.05, 0.8, 16);
  const shaftMat = new MeshPhysicalNodeMaterial();
  shaftMat.colorNode = color('#16161d');
  shaftMat.roughness = 0.4;
  shaftMat.metalness = 0.6;
  disposables.push(shaftGeo, shaftMat);

  const shaftPrimary = new THREE.Mesh(shaftGeo, shaftMat);
  shaftPrimary.rotation.x = Math.PI / 2;
  primaryGroup.add(shaftPrimary);

  const shaftSecondary = new THREE.Mesh(shaftGeo, shaftMat);
  shaftSecondary.rotation.x = Math.PI / 2;
  secondaryGroup.add(shaftSecondary);

  // Contact shadow ellipse
  const shadowGeo = new THREE.CircleGeometry(1, 48);
  shadowGeo.scale(2.6, 1.2, 1);
  const shadowMat = new MeshPhysicalNodeMaterial();
  shadowMat.colorNode = color('#000000');
  shadowMat.transparent = true;
  shadowMat.opacity = 0.5;
  shadowMat.roughness = 1.0;
  shadowMat.metalness = 0.0;
  const shadowMesh = new THREE.Mesh(shadowGeo, shadowMat);
  shadowMesh.rotation.x = -Math.PI / 2;
  shadowMesh.position.set(0, -1.2, 0);
  root.add(shadowMesh);
  disposables.push(shadowGeo, shadowMat);

  // Backdrop plane with gradient
  const bgGeo = new THREE.PlaneGeometry(7, 6);
  const bgMat = new MeshPhysicalNodeMaterial();
  bgMat.colorNode = color('#101017');
  bgMat.roughness = 1.0;
  bgMat.metalness = 0.0;
  const bgMesh = new THREE.Mesh(bgGeo, bgMat);
  bgMesh.position.set(0, 0, -3);
  root.add(bgMesh);
  disposables.push(bgGeo, bgMat);

  root.fog = new THREE.Fog('#0b0b10', 5, 11);

  // Text content
  const headline = createText(ctx.fontAtlas, {
    text: 'The going train',
    fontFamily: 'Lora',
    fontSize: 68,
    fontWeight: 600,
    letterSpacing: -0.005,
    lineHeight: 1.1,
    color: '#e8ecf2',
  });
  headline.position.set(0, -1.7, 0);
  root.add(headline);

  const caption = createText(ctx.fontAtlas, {
    text: '34 COMPONENTS / HAND-FINISHED',
    fontFamily: 'JetBrains Mono',
    fontSize: 18,
    fontWeight: 400,
    letterSpacing: 0.08,
    lineHeight: 1.4,
    color: '#e8ecf2',
  });
  caption.position.set(0, -2.1, 0);
  root.add(caption);

  // Apply cinematic primitive: orbit
  if (config.cinematicPrimitives) {
    config.cinematicPrimitives.forEach((prim) => {
      if (ctx.primitives[prim.name]) {
        ctx.primitives[prim.name](root, prim.params);
      }
    });
  }

  // Meshing gear rotation animation via GSAP ticker
  const rotationState = { primary: 0, secondary: 0 };
  const primarySpeed = 0.08;
  const secondarySpeed = -0.142;

  const tickFn = (time, deltaTime) => {
    const dt = deltaTime || 0;
    rotationState.primary += primarySpeed * dt;
    rotationState.secondary += secondarySpeed * dt;
    primaryGroup.rotation.z = rotationState.primary;
    secondaryGroup.rotation.z = rotationState.secondary;
  };
  gsap.ticker.add(tickFn);
  timelines.push({ kill: () => gsap.ticker.remove(tickFn) });

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill && tl.kill());
    disposables.forEach((res) => res.dispose && res.dispose());
    root.traverse((child) => {
      if (child.isMesh) {
        child.geometry?.dispose?.();
        if (child.material && child.material !== steelMat) {
          child.material.dispose?.();
        }
      }
    });
    steelMat.dispose?.();
  };

  return root;
}
